const recList = `-- name: RecList :many
SELECT id, workspace_id, kind, name, description, logo_id, url, partner_link_id, show_confirm, show_block, status, paused_at, paused_by, position, created_by, created_at, updated_at, removed_at FROM recommendations WHERE workspace_id = $1 AND removed_at IS NULL ORDER BY position, created_at
`

func (q *Queries) RecList(ctx context.Context, workspaceID uuid.UUID) ([]Recommendation, error) {
	rows, err := q.db.Query(ctx, recList, workspaceID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Recommendation{}
	for rows.Next() {
		var i Recommendation
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.Kind,
			&i.Name,
			&i.Description,
			&i.LogoID,
			&i.Url,
			&i.PartnerLinkID,
			&i.ShowConfirm,
			&i.ShowBlock,
			&i.Status,
			&i.PausedAt,
			&i.PausedBy,
			&i.Position,
			&i.CreatedBy,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.RemovedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

